def _rows(b: Builder, items: list[tuple[str, str]], category: str, prefix: str) -> None:
    for i, (q, a) in enumerate(items):
        b.add(q, a, category, fact=f"{prefix}-{i}", min_answer=30)


def build_chat(b: Builder) -> None:
    _rows(b, IDENTITY, "percakapan", "identitas")
    _rows(b, GREETINGS, "percakapan", "sapaan")
    _rows(b, EMOTIONS, "percakapan", "emosi")
    _rows(b, SMALLTALK, "percakapan", "obrolan")
    _rows(b, CAPABILITIES, "percakapan", "kemampuan")
    _rows(b, SAFETY, "percakapan", "aman")
    _rows(b, META, "percakapan", "meta")
    _rows(b, RIDDLES, "percakapan", "teka")
    _rows(b, JOKES, "percakapan", "lelucon")
    _rows(b, CODE, "kode", "kode", )
